// DEV_RIO_602 Sales Funnel【LINE フォローアップ・下書き準備】
// リードのステータスに応じた段階的なフォローアップメッセージを LINE で準備。
const i = $input.first().json;
return [{ json: {
  funnel_stage: i.funnel_stage ?? 'awareness',
  lead_id: i.lead_id ?? 'lead-' + Math.random().toString(36).substr(2, 9),
  line_user_id: i.line_user_id ?? 'U' + Math.random().toString(36).substr(2, 9),
  days_in_funnel: i.days_in_funnel ?? 3,
  platform: 'line',
  action_type: 'send_funnel_followup'
} }];

// ファネルステージに応じたフォローアップメッセージをClaude生成
const i = $input.first().json;
const stageDesc = {
  awareness: '認識段階：製品を知り始めた段階',
  consideration: '検討段階：購入を検討している段階',
  decision: '決定段階：購入直前の段階'
};
const prompt = `リードの営業ファネルステージが「${stageDesc[i.funnel_stage] || '不明'}」です。\nファネルステージに適したLINE フォローアップメッセージの下書きを作成してください。\n\n条件:\n- 100字以内、日本語\n- ステージに合わせた行動喚起（CTA）\n- 次のステップへ進むよう促す\n- 出力は次のJSON配列のみ: [{"subject":"string","followup_message":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。ファネル段階別のフォローアップ下書き生成
const input = $input.first().json;
const ctx = $('Collect Funnel Input').first().json;
let followups = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    followups = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(followups) || followups.length === 0) throw new Error('followups missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) followups = [{ subject: '手動作成', followup_message: '（AI応答の取得/解析に失敗。手動でフォローアップを作成してください）' }];
return [{ json: {
  lead_id: ctx.lead_id,
  line_user_id: ctx.line_user_id,
  funnel_stage: ctx.funnel_stage,
  followup_messages: followups,
  state: 'WAITING_APPROVAL',
  published: false,
  draft_error: parse_error,
  note: 'ドライラン。ファネル段階別フォローアップ下書きのみ。自動送信はしない。人間が確認して手動実行。'
} }];
